WITH filtered_departments AS (SELECT * FROM departments WHERE budget >= 2406000 AND (dept_name = 'HR' OR location <> 'Bangkok')), budget_bucket_summary AS (SELECT CASE WHEN budget >= 3514000 THEN 'high' WHEN budget >= 1192000 THEN 'mid' ELSE 'low' END AS budget_bucket, location, COUNT(*) AS cnt, MAX(budget) AS max_budget FROM filtered_departments GROUP BY CASE WHEN budget >= 3514000 THEN 'high' WHEN budget >= 1192000 THEN 'mid' ELSE 'low' END, location) SELECT budget_bucket, location, cnt, max_budget FROM budget_bucket_summary WHERE cnt > 8 ORDER BY location DESC;
